TYPE TNameSet = SET OF STRING

DEFINE Chess ("Ana", "Ben", "Chen", "Dev", "Eli") : TNameSet
DEFINE Robotics ("Chen", "Eli", "Farah", "Gus") : TNameSet

// The guide defines no keywords for membership, union or intersection;
// use the notation a question gives you, or describe the operation.

Chess    = {Ana, Ben, Chen, Dev, Eli}
Robotics = {Chen, Eli, Farah, Gus}

Intersection (in both clubs):          {Chen, Eli}
Union (in at least one club):          {Ana, Ben, Chen, Dev, Eli, Farah, Gus}  7 members, not 9
Difference Chess - Robotics:           {Ana, Ben, Dev}
Is Gus a member of Robotics?           yes

Removing duplicates: the list Ben, Ana, Ben, Chen loaded into a set gives {Ana, Ben, Chen}.
(All results checked with Python set operations &, |, - and in.)

// A trip takes up to 40 students. For each: ID (e.g. "S0417"), surname, date of birth,
// payment status (unpaid, deposit paid or fully paid) and one dietary need,
// which must be one of the needs the caterer can supply.

TYPE TPayment = (Unpaid, Deposit, Paid)

TYPE TNeedSet = SET OF STRING
DEFINE Catered ("None", "Vegetarian", "Vegan", "Halal", "Gluten free") : TNeedSet

TYPE TTraveller
   DECLARE StudentID : STRING         // leading zero, never used in arithmetic
   DECLARE Surname : STRING
   DECLARE DateOfBirth : DATE
   DECLARE Payment : TPayment
   DECLARE DietaryNeed : STRING       // validated against the Catered set
ENDTYPE

DECLARE Trip : ARRAY[1:40] OF TTraveller

// Justification: payment has three fixed ordered stages (enumerated, so Payment >= Deposit
// finds everyone who has paid something); each student is several facts of different
// types (record); up to 40 students (array of records); the caterer's options are a
// collection checked only for membership (set).
